const stage=document.querySelector('#book-stage'),prev=document.querySelector('#book-prev'),next=document.querySelector('#book-next'),count=document.querySelector('#book-count'),desc=document.querySelector('#book-description'),fallbackTitle=document.querySelector('#fallback-title'),fallbackItems=document.querySelector('#fallback-items');
const pages=[{title:'Biryani',items:['Mutton Biryani','Chicken Biryani','Kebabs'],photos:['biryani','biryani','kebabs']},{title:'Kebabs',items:['Chicken Tikka Kabab','Chicken Reshmi Kabab','Kebab Platter'],photos:['kebabs','kebabs','kebabs']},{title:'The wider table',items:['Mughlai favourites','Indo-Chinese dishes','Biryani & rice'],photos:['kebabs','kebabs','biryani']},{title:'At Sufi Palace',items:['Explore the full menu','Visit College Street','Ask us about catering'],photos:['biryani','store','kebabs']}];
const W=2.35,H=3.5;let current=0,turning=false,renderer,scene,camera,book,leftPage,rightPage,turnFront,turnBack,artTexture,textures=[],direction=1,started=0,raf=0;const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;const photos={};
