function pageTexture(p){const canvas=document.createElement('canvas');canvas.width=1000;canvas.height=1500;const c=canvas.getContext('2d');c.fillStyle='#f3dfbd';c.fillRect(0,0,1000,1500);const g=c.createLinearGradient(0,0,1000,0);g.addColorStop(0,'#b9a080');g.addColorStop(.07,'#e5cda9');g.addColorStop(.2,'#f5e6cb');g.addColorStop(.8,'#f0dab7');g.addColorStop(1,'#dac09a');c.fillStyle=g;c.fillRect(0,0,1000,1500);let seed=71;for(let k=0;k<18000;k++){seed=(seed*16807)%2147483647;const x=seed%1000;seed=(seed*16807)%2147483647;const y=seed%1500;c.fillStyle=k%2?'#653f2410':'#ffffff25';c.fillRect(x,y,1,1)}c.strokeStyle='#b98b52';c.lineWidth=2;c.strokeRect(35,35,930,1430);c.strokeRect(48,48,904,1404);ornament(c,500,104,1.4);[[83,90],[917,90],[83,1405],[917,1405]].forEach(([x,y])=>ornament(c,x,y,.8));c.textAlign='center';c.fillStyle='#48211a';c.font='92px Georgia';c.fillText(p.title,500,270);c.strokeStyle='#b88c55';c.beginPath();c.moveTo(280,310);c.lineTo(720,310);c.stroke();p.items.forEach((item,i)=>{const cy=465+i*305;const img=photos[p.photos[i]];c.save();c.beginPath();c.ellipse(266,cy,150,104,0,0,7);c.clip();if(img){const scale=Math.max(300/img.width,208/img.height);c.drawImage(img,266-img.width*scale/2,cy-img.height*scale/2,img.width*scale,img.height*scale)}c.restore();c.strokeStyle='#b78a50';c.lineWidth=2;c.beginPath();c.ellipse(266,cy,150,104,0,0,7);c.stroke();c.fillStyle='#563123';c.font='38px Georgia';c.textAlign='left';const words=item.split(' ');let lines=[''];for(const word of words){let idx=lines.length-1;if(c.measureText(lines[idx]+word).width>390)lines.push(word+' ');else lines[idx]+=word+' '}lines.forEach((line,j)=>c.fillText(line.trim(),460,cy+(j-(lines.length-1)/2)*48+9));c.beginPath();c.moveTo(460,cy+65);c.lineTo(840,cy+65);c.stroke();ornament(c,650,cy+65,.45)});c.textAlign='center';c.fillStyle='#9b7954';c.font='21px Georgia';c.fillText('Please confirm current availability and prices',500,1390);return texture(canvas)}
function noiseTexture(marble=false){const c=document.createElement('canvas');c.width=c.height=512;const x=c.getContext('2d');x.fillStyle=marble?'#53392f':'#451317';x.fillRect(0,0,512,512);let seed=18;for(let k=0;k<18000;k++){seed=(seed*16807)%2147483647;let a=seed%512;seed=(seed*16807)%2147483647;let b=seed%512;x.fillStyle=k%2?'#ffffff10':'#00000018';x.fillRect(a,b,2,2)}if(marble){x.lineWidth=.8;for(let j=0;j<20;j++){x.strokeStyle=j%2?'#e6d0aa66':'#d0a17033';x.beginPath();x.moveTo(-30,j*35);x.bezierCurveTo(170,j*35-100,240,j*35+90,560,j*35-40);x.stroke()}}return texture(c)}
function pageGeo(side){const g=new THREE.PlaneGeometry(W,H,60,12);g.translate(side*W/2,0,0);const p=g.attributes.position;for(let i=0;i<p.count;i++){const x=p.getX(i);p.setZ(i,.045+Math.sin(Math.abs(x)/W*Math.PI)*.065-Math.abs(x)/W*.045)}g.computeVertexNormals();return g}
function render(){if(renderer)renderer.render(scene,camera)}
function createBox(w,h,d,material,x,y,z,parent=scene){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
async function init(){try{renderer=new THREE.WebGLRenderer({alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0x000000,0);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;stage.appendChild(renderer.domElement);const images=await Promise.all([loadImage('assets/book-art-page.webp'),loadImage('assets/biryani.png'),loadImage('assets/kebabs.png'),loadImage('assets/storefront.webp')]);photos.biryani=images[1];photos.kebabs=images[2];photos.store=images[3];artTexture=texture(images[0]);textures=pages.map(pageTexture);scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(36,1,.1,100);scene.add(new THREE.HemisphereLight(0xffe6c0,0x321015,2));const key=new THREE.DirectionalLight(0xffe0b4,3);key.position.set(-4,6,7);key.castShadow=true;key.shadow.mapSize.set(2048,2048);Object.assign(key.shadow.camera,{left:-6,right:6,top:6,bottom:-6,near:.1,far:25});key.shadow.bias=-.0003;key.shadow.normalBias=.015;key.shadow.radius=4;scene.add(key);const fill=new THREE.DirectionalLight(0xffbb65,1);fill.position.set(4,1,3);scene.add(fill);const marble=new THREE.MeshPhysicalMaterial({map:noiseTexture(true),roughness:.26,clearcoat:.7,clearcoatRoughness:.25,color:0xf1e1ce});createBox(5.7,.22,2.0,marble,0,-2.02,-.1);const bronze=new THREE.MeshStandardMaterial({color:0x9b6b32,metalness:.7,roughness:.35});createBox(5.72,.022,.025,bronze,0,-1.9,.91);const wood=new THREE.MeshStandardMaterial({map:noiseTexture(),color:0x731f22,roughness:.6});createBox(4.95,.11,.58,wood,0,-1.81,-.18);createBox(4.95,.04,.06,bronze,0,-1.74,.12);const backStand=createBox(4.55,1.9,.11,wood,0,-.8,-.44);backStand.rotation.x=-.12;book=new THREE.Group();book.position.y=.02;book.rotation.x=-.13;book.rotation.y=-.09;scene.add(book);for(const side of [-1,1]){const wing=new THREE.Group();wing.rotation.y=side*.10;book.add(wing);const cover=createBox(W+.13,H+.15,.11,wood,side*(W/2+.015),0,-.13,wing);createBox(W+.09,H+.10,.025,bronze,side*(W/2+.015),0,-.062,wing);const paper=new THREE.MeshStandardMaterial({color:0xd7bd96,roughness:.98});createBox(W,H,.13,paper,side*W/2,0,-.015,wing);for(let k=0;k<9;k++){const line=new THREE.LineSegments(new THREE.EdgesGeometry(new THREE.BoxGeometry(W,H,.001)),new THREE.LineBasicMaterial({color:k%2?0xb99d77:0xead6b3,transparent:true,opacity:.7}));line.position.set(side*W/2,0,-.06+k*.014);wing.add(line)}const pg=new THREE.Mesh(pageGeo(side),new THREE.MeshStandardMaterial({map:side<0?artTexture:textures[0],roughness:.95,side:THREE.FrontSide}));pg.position.z=.08;pg.castShadow=true;pg.receiveShadow=true;wing.add(pg);if(side<0)leftPage=pg;else rightPage=pg}const tg=new THREE.PlaneGeometry(W,H,72,12);tg.translate(W/2,0,0);turnFront=new THREE.Mesh(tg,new THREE.MeshStandardMaterial({map:textures[0],roughness:.94,side:THREE.FrontSide}));turnBack=new THREE.Mesh(tg.clone(),new THREE.MeshStandardMaterial({map:artTexture,roughness:.94,side:THREE.BackSide}));for(const m of [turnFront,turnBack]){m.position.z=.14;m.castShadow=true;m.receiveShadow=true;m.visible=false;book.add(m)}stage.classList.add('ready');function resize(){const w=stage.clientWidth,h=stage.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;const dist=Math.max(4.45/(2*Math.tan(Math.PI/10)),5.9/(2*Math.tan(Math.PI/10)*camera.aspect));camera.position.set(.15,.35,dist);camera.lookAt(0,-.15,0);camera.updateProjectionMatrix();render()}new ResizeObserver(resize).observe(stage);resize()}catch(err){console.error('Menu 3D unavailable:',err);renderer?.domElement.remove();renderer=null;stage.classList.remove('ready')}}
function setMap(mesh,map){mesh.material.map=map;mesh.material.needsUpdate=true}
function settle(){setMap(rightPage,textures[current]);setMap(leftPage,current===0?artTexture:textures[current-1]);render()}
function turn(dir){const target=current+dir;if(turning||target<0||target>3)return;if(!renderer||!scene||reduce){current=target;updateText();if(scene)settle();return}turning=true;direction=dir;started=performance.now();setMap(turnFront,textures[dir>0?current:target]);setMap(turnBack,dir>0?textures[current]:textures[target]);setMap(rightPage,textures[dir>0?target:current]);setMap(leftPage,target===0?artTexture:textures[Math.max(0,(dir>0?current:target)-1)]);turnFront.visible=turnBack.visible=true;raf=requestAnimationFrame(animate)}
function animate(now){const t=Math.min(1,(now-started)/1450),s=t*t*(3-2*t),progress=direction>0?s:1-s;for(const mesh of [turnFront,turnBack]){const a=mesh.geometry.attributes.position;const cols=73;for(let i=0;i<a.count;i++){const u=(i%cols)/(cols-1);let x=0,z=0;const steps=30;for(let j=0;j<steps;j++){const f=u*(j+.5)/steps;const theta=-Math.PI*progress+Math.sin(Math.PI*progress)*Math.sin(f*Math.PI)*.85;x+=Math.cos(theta)*W*u/steps;z-=Math.sin(theta)*W*u/steps}a.setX(i,x);a.setZ(i,z+.045*Math.sin(u*Math.PI))}a.needsUpdate=true;mesh.geometry.computeVertexNormals()}render();if(t<1)raf=requestAnimationFrame(animate);else{current+=direction;turnFront.visible=turnBack.visible=false;turning=false;updateText();settle()}}
prev.addEventListener('click',()=>turn(-1));next.addEventListener('click',()=>turn(1));let px=null;stage.addEventListener('pointerdown',e=>{px=e.clientX;stage.setPointerCapture(e.pointerId)});stage.addEventListener('pointerup',e=>{if(px===null)return;const delta=e.clientX-px;px=null;if(Math.abs(delta)>40)turn(delta<0?1:-1)});stage.addEventListener('pointercancel',()=>px=null);init();
